rewanted-cafe.css:
.bx-stars{position:relative;height:72px;margin:10px auto;max-width:260px}
.bx-st{position:absolute;color:var(--accent);opacity:.7;font-size:14px;transition:opacity .4s,text-shadow .4s}
.bx-s1{top:4px;left:12%}.bx-s2{top:26px;left:38%;font-size:10px}.bx-s3{top:8px;left:64%;font-size:18px}.bx-s4{top:40px;left:80%}.bx-s5{top:48px;left:22%;font-size:9px}
.bx-note-ar{position:absolute;bottom:-6px;right:0;font-size:12px;color:var(--text-2);letter-spacing:.02em}
.bx-stars:hover .bx-st{opacity:1;text-shadow:0 0 12px var(--accent)}
@media (prefers-reduced-motion: no-preference){
.bx-st{animation:bx-tw 3.2s ease-in-out infinite}
.bx-s2{animation-delay:.6s}.bx-s3{animation-delay:1.1s}.bx-s4{animation-delay:1.7s}.bx-s5{animation-delay:2.3s}
@keyframes bx-tw{0%,100%{opacity:.35}50%{opacity:1;text-shadow:0 0 10px var(--accent)}}
}

solio-cafe.css:
.bx-sun{position:relative;width:120px;height:84px;margin:10px auto 24px;display:grid;place-items:center}
.bx-sunrays{position:absolute;width:76px;height:76px;border-radius:50%;background:repeating-conic-gradient(var(--sa) 0 6deg,transparent 6deg 24deg);-webkit-mask:radial-gradient(circle,transparent 42%,#000 44%);mask:radial-gradient(circle,transparent 42%,#000 44%);opacity:.45;transition:transform .8s ease,opacity .8s ease;transform:scale(var(--bx-s,1))}
.bx-suncore{width:34px;height:34px;border-radius:50%;background:radial-gradient(circle at 35% 30%,var(--sa),var(--accent));box-shadow:0 0 18px 2px var(--sa)}
.bx-sun:hover .bx-sunrays{--bx-s:1.25;opacity:.8}
.bx-sunnote{position:absolute;bottom:-14px;font-size:12px;color:var(--text-2);white-space:nowrap}
@media (prefers-reduced-motion: no-preference){
.bx-sunrays{animation:bx-spin 40s linear infinite}
@keyframes bx-spin{from{transform:rotate(0deg) scale(var(--bx-s,1))}to{transform:rotate(360deg) scale(var(--bx-s,1))}}
}

laminam-cafe.css:
.bx-carve{display:grid;place-items:center;gap:6px;margin:14px auto;width:fit-content}
.bx-tile{width:52px;height:52px;filter:drop-shadow(0 1px 0 rgba(255,255,255,.06)) drop-shadow(0 -1px 1px rgba(0,0,0,.35));transition:filter .6s ease}
.bx-tq{fill:none;stroke:var(--accent);stroke-width:1.5;opacity:.55;transition:opacity .6s}
.bx-tq2{transform:rotate(45deg);transform-origin:24px 24px}
.bx-tc{fill:var(--sa);opacity:.4;transition:opacity .6s}
.bx-carve:hover .bx-tq{opacity:.95}
.bx-carve:hover .bx-tc{opacity:.85}
.bx-carve:hover .bx-tile{filter:drop-shadow(0 0 8px var(--sa))}
.bx-carvenote{font-size:12px;color:var(--text-2)}
@media (prefers-reduced-motion: no-preference){
.bx-tc{animation:bx-emb 6s ease-in-out infinite}
@keyframes bx-emb{0%,100%{opacity:.3}50%{opacity:.6}}
}

lihaf.css:
.bx-quilt{position:relative;display:inline-block;margin:1.1em auto;padding:.85em 1.5em;border:2px dashed var(--sa);border-radius:16px;background:repeating-linear-gradient(45deg,transparent 0 13px,color-mix(in srgb,var(--accent) 9%,transparent) 13px 14px),repeating-linear-gradient(-45deg,transparent 0 13px,color-mix(in srgb,var(--accent) 9%,transparent) 13px 14px);transition:transform .5s ease,box-shadow .5s ease;cursor:default}
.bx-quilt:hover{transform:rotate(-1.6deg) scale(1.05);box-shadow:0 8px 22px -10px var(--accent)}
.bx-quilt-note{font-size:.95em;color:var(--text-2);letter-spacing:.02em}
.bx-quilt::after{content:"❋";position:absolute;top:-.75em;inset-inline-end:-.45em;color:var(--accent);font-size:1.05em}
@media (prefers-reduced-motion:no-preference){.bx-quilt{animation:bx-warmth 6s ease-in-out infinite}@keyframes bx-warmth{0%,100%{box-shadow:0 0 0 0 transparent}50%{box-shadow:0 10px 26px -12px var(--accent)}}}

mat-cookies.css:
.bx-start{display:inline-flex;align-items:center;gap:.45em;margin:1.1em auto;padding:.6em 1.1em;border:2px solid var(--accent);outline:2px solid var(--sa);outline-offset:3px;border-radius:2px;font-size:.95em;color:var(--text-2);letter-spacing:.06em;transition:text-shadow .3s ease,box-shadow .3s ease;cursor:default}
.bx-start:hover{color:var(--accent);text-shadow:0 0 8px var(--accent);box-shadow:0 0 14px -4px var(--accent),inset 0 0 10px -6px var(--sa)}
.bx-cursor{color:var(--accent)}
@media (prefers-reduced-motion:no-preference){.bx-cursor{animation:bx-blink 1.1s steps(1) infinite}@keyframes bx-blink{0%,100%{opacity:1}50%{opacity:0}}.bx-start:hover{animation:bx-neon 1.6s ease-in-out infinite}@keyframes bx-neon{0%,100%{box-shadow:0 0 10px -4px var(--accent)}50%{box-shadow:0 0 20px -2px var(--accent)}}}

secret-pot-bakery.css:
.bx-ticket{position:relative;display:inline-flex;flex-direction:column;align-items:center;gap:.3em;margin:1.4em auto .9em;padding:.8em 1.6em;border:1.5px dashed var(--sa);border-radius:6px;cursor:default}
.bx-ticket::before,.bx-ticket::after{content:"";position:absolute;top:50%;width:12px;height:12px;border-radius:50%;border:1.5px dashed var(--sa);background:inherit;transform:translateY(-50%)}
.bx-ticket::before{inset-inline-start:-7px}
.bx-ticket::after{inset-inline-end:-7px}
.bx-ticket-note{font-size:.95em;color:var(--text-2);letter-spacing:.03em}
.bx-steam{display:flex;gap:5px;height:16px;align-items:flex-end}
.bx-steam i{width:3px;height:12px;border-radius:3px;background:var(--accent);opacity:.3;filter:blur(.4px)}
@media (prefers-reduced-motion:no-preference){.bx-steam i{animation:bx-rise 3.2s ease-in-out infinite}.bx-steam i:nth-child(2){animation-delay:.6s;height:15px}.bx-steam i:nth-child(3){animation-delay:1.2s}@keyframes bx-rise{0%{transform:translateY(4px) skewX(0);opacity:0}40%{opacity:.5}100%{transform:translateY(-9px) skewX(8deg);opacity:0}}}
